create extension if not exists pgcrypto;
create table organisation(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz not null default now());
create table app_user(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,identity_subject text not null,email text not null,display_name text not null,active boolean not null default true,unique(organisation_id,identity_subject),unique(organisation_id,email));
create table board(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,slug text not null,portfolio text,created_at timestamptz not null default now(),unique(organisation_id,slug));
create table work_item(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,board_id uuid not null references board(id) on delete cascade,parent_id uuid references work_item(id) on delete set null,title text not null,description text not null default '',status text not null default 'planned' check(status in('planned','in_progress','blocked','review','done','cancelled')),owner_id uuid references app_user(id) on delete set null,estimate numeric(8,2),starts_on date,due_on date,completed_at timestamptz,custom_values jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index work_item_search_idx on work_item using gin(to_tsvector('english',title||' '||description));
create table item_dependency(predecessor_id uuid not null references work_item(id) on delete cascade,successor_id uuid not null references work_item(id) on delete cascade,lag_days integer not null default 0,primary key(predecessor_id,successor_id),check(predecessor_id<>successor_id));
create table automation(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,version integer not null default 1,definition jsonb not null,active boolean not null default false,created_at timestamptz not null default now(),unique(organisation_id,name,version));
create table automation_run(id uuid primary key default gen_random_uuid(),automation_id uuid not null references automation(id),work_item_id uuid references work_item(id),status text not null check(status in('queued','running','succeeded','failed','skipped')),result jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table audit_event(id bigint generated always as identity primary key,organisation_id uuid not null references organisation(id) on delete cascade,actor_id text not null,action text not null,entity_type text not null,entity_id text not null,payload jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now());
create table role_policy(organisation_id uuid not null references organisation(id) on delete cascade,role_key text not null,permissions text[] not null default '{}',updated_by text not null,updated_at timestamptz not null default now(),primary key(organisation_id,role_key));
